import {api,uploadFiles} from './services.js';
import {personalLoanChecklist,checklistCount,checklistStatus,classificationOptions} from './checklist.js';

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const humanDate=x=>x?new Date(x).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const statusClass=s=>String(s||'').toLowerCase().replaceAll(' ','-');
const badge=s=>`<span class="status ${statusClass(s)}"><i></i>${esc(s||'Pending')}</span>`;
const money=x=>x==null?'—':'₹'+Number(x).toLocaleString('en-IN',{maximumFractionDigits:0});
const initials=x=>String(x||'L').split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
const safeId=x=>esc(String(x||'').replace(/[^a-zA-Z0-9_-]/g,''));
const state={role:'applicant',view:'applicant-overview',filter:'All',query:'',sort:'created_at',sortDir:-1,page:1,pageSize:8,selected:null,applicantId:'',caseTab:'summary',finding:null,docId:null,checkFilter:'All',notifications:false,playback:[],playIndex:0,playing:false,formStep:0,formData:{},uploadProgress:null,requestTab:'Open',formOrigin:'overview',user:null};

function renderAuth(mode='login',error='',errorType='error'){const screen=$('#auth-screen');document.body.classList.add('unauthenticated');screen.hidden=false;screen.innerHTML=`<div class="auth-layout"><aside class="auth-story"><div class="auth-story-grid"></div><div class="auth-story-content"><div class="auth-brand"><span class="auth-brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 2.8 20 6v5.4c0 5.2-3.3 8.4-8 10.2-4.7-1.8-8-5-8-10.2V6l8-3.2Z"/><path d="m8.5 12.2 2.2 2.2 4.8-5"/></svg></span><span>LoanDoc<span>Verify</span></span></div><div class="auth-story-copy"><div class="auth-kicker"><i></i> INTELLIGENT LOAN REVIEW</div><h1>Document verification.<br><span>Made intelligent.</span></h1><p>An AI-powered verification platform that simplifies loan document review, identifies inconsistencies, and helps teams make informed decisions.</p></div><section class="workflow-preview" aria-label="How loan document review works"><div class="workflow-heading"><span class="workflow-kicker">HOW THE WORKSPACE WORKS</span><strong>From documents to evidence-backed findings</strong></div><div class="workflow-step"><span class="workflow-number">01</span><span><strong>Add loan documents</strong><small>Keep each applicant’s files with their application.</small></span></div><div class="workflow-step"><span class="workflow-number">02</span><span><strong>Compare extracted details</strong><small>Review identity, income, and document consistency.</small></span></div><div class="workflow-step"><span class="workflow-number">03</span><span><strong>Inspect findings and evidence</strong><small>Open source documents before making a human decision.</small></span></div></section><div class="auth-story-foot"><span>Built for clarity, accuracy, and responsible verification.</span><span class="story-foot-mark">LOANDOCVERIFY · WORKSPACE</span></div></div></aside><main class="auth-form-panel"><div class="auth-form-wrap"><div class="auth-form-top"><span class="auth-mobile-brand"><span class="auth-brand-mark" aria-hidden="true">L</span>LoanDoc<span>Verify</span></span><span>Secure workspace access</span></div><div class="auth-eyebrow">LOAN DOCUMENT WORKSPACE</div><h2>${mode==='login'?'Welcome back':'Create your account'}</h2><p class="auth-copy">${mode==='login'?'Sign in to continue to your LoanDocVerify workspace.':'Set up an account to submit and verify your loan applications.'}</p>${error?`<div class="auth-${errorType}" role="${errorType==='error'?'alert':'status'}"><span aria-hidden="true">${errorType==='error'?'!':'i'}</span>${esc(error)}</div>`:''}<form id="auth-form" data-mode="${mode}" novalidate>${mode==='signup'?'<label class="auth-field">Your name<div class="auth-input-wrap"><span aria-hidden="true">♙</span><input name="name" autocomplete="name" placeholder="Enter your full name" required></div></label><label class="auth-field">Account type<select class="input" name="role" required><option value="applicant">Applicant</option><option value="officer">Loan officer</option></select></label>':''}<label class="auth-field">Email address<div class="auth-input-wrap"><span aria-hidden="true">✉</span><input name="email" type="email" autocomplete="email" placeholder="Enter your email address" required></div></label><label class="auth-field">Password<div class="auth-input-wrap"><span aria-hidden="true">⌑</span><input id="auth-password" name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="10" placeholder="Enter your password" required><button type="button" class="password-toggle" aria-label="Show password" aria-pressed="false" data-auth-password><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.8 12s3.2-6 9.2-6 9.2 6 9.2 6-3.2 6-9.2 6-9.2-6-9.2-6Z"/><circle cx="12" cy="12" r="2.5"/></svg></button></div>${mode==='signup'?'<small>Use at least 10 characters.</small>':''}</label>${mode==='login'?`<div class="auth-options"><label class="remember-option"><input type="checkbox" name="remember" ${localStorage.getItem('ldv-remember')==='on'?'checked':''}><span>Remember me</span></label><button type="button" class="auth-text-link" data-auth-forgot>Forgot password?</button></div>`:''}<button class="btn primary auth-submit" type="submit"><span class="auth-submit-label">${mode==='login'?'Sign in':'Create account'}</span><span class="auth-spinner" aria-hidden="true"></span><span aria-hidden="true">→</span></button></form><p class="auth-switch">${mode==='login'?`Don't have an account?`:'Already have an account?'} <button type="button" class="link-btn" data-auth-mode="${mode==='login'?'signup':'login'}">${mode==='login'?'Create account':'Sign in'}</button></p><div class="auth-divider"><span></span><small>YOUR ACCOUNT</small><span></span></div><p class="auth-account-note">Each account has one role. Applicants share an application with their chosen loan officer using a one-time invitation code.</p></div><footer class="auth-page-footer"><span>© ${new Date().getFullYear()} LoanDocVerify</span><span>Privacy&nbsp;&nbsp; · &nbsp;&nbsp;Terms&nbsp;&nbsp; · &nbsp;&nbsp;Help</span></footer></main></div>`}
async function submitAuth(form){if(state.authBusy)return;const data=Object.fromEntries(new FormData(form));const email=form.elements.email,password=form.elements.password;if(!email.value.trim()||!email.validity.valid){email.setCustomValidity('Enter a valid email address.');email.reportValidity();email.setCustomValidity('');email.focus();return}if(!password.value){password.setCustomValidity('Enter your password.');password.reportValidity();password.setCustomValidity('');password.focus();return}if(form.dataset.mode==='signup'&&password.value.length<10){password.setCustomValidity('Use at least 10 characters.');password.reportValidity();password.setCustomValidity('');password.focus();return}state.authBusy=true;const submit=form.querySelector('.auth-submit');submit.disabled=true;submit.setAttribute('aria-busy','true');submit.querySelector('.auth-submit-label').textContent=form.dataset.mode==='login'?'Signing in…':'Creating account…';try{if(data.remember)localStorage.setItem('ldv-remember','on');else localStorage.removeItem('ldv-remember');const result=await api(`/auth/${form.dataset.mode}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,remember:!!data.remember})});state.user=result.user;document.body.classList.remove('unauthenticated');$('#auth-screen').hidden=true;localStorage.removeItem('ldv-applicant');state.applicantId='';await initWorkspace()}catch(e){const message=/failed to fetch|networkerror|load failed/i.test(e.message||'')?'Could not reach LoanDocVerify. Check that the local service is running, then try again.':e.message;renderAuth(form.dataset.mode,message)}finally{state.authBusy=false}}
async function signOut(){try{await api('/auth/logout',{method:'POST'})}catch{}state.user=null;state.data=null;state.applicant=null;state.applicantId='';state.selected=null;state.loadError=null;renderAuth('login')}
async function initWorkspace(){state.loadError=null;state.selected=null;state.applicant=null;const avatar=initials(state.user?.name),avatarEl=$('.top-avatar'),nameEl=$('.user-card strong');if(avatarEl)avatarEl.textContent=avatar;if(nameEl)nameEl.textContent=state.user?.name||'Workspace member';state.role=state.user?.role||'applicant';state.view=state.role==='officer'?'overview':'applicant-overview';updateShell();try{state.data=await api('/dashboard')}catch(error){state.loadError=error}await render()}

function toast(message,tone='success'){const box=$('#toast');box.className=`toast ${tone} show`;box.textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),3300)}
function loading(title='Loading workspace'){return `<div class="skeleton-page" aria-label="${title}"><div class="skeleton-line w40"></div><div class="skeleton-line w60"></div><div class="skeleton-grid">${[1,2,3,4].map(()=>'<div class="skeleton-card"></div>').join('')}</div><div class="skeleton-card tall"></div></div>`}
function empty(title,detail,action='',label=''){return `<div class="empty-state"><span class="empty-icon">⌕</span><strong>${esc(title)}</strong><p>${esc(detail)}</p>${action?`<button class="btn primary" data-action="${action}">${esc(label)}</button>`:''}</div>`}
function apiError(error,retryAction='retry'){return `<div class="inline-alert error"><span>!</span><div><strong>We couldn’t load this information.</strong><p>${esc(error.message||error)}</p><button class="link-btn" data-action="${retryAction}">Try again</button></div></div>`}
function showModal(title,body,actions=''){const m=$('#dialog');m.innerHTML=`<div class="dialog-backdrop" data-action="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></header><div class="dialog-body">${body}</div>${actions?`<footer class="dialog-foot">${actions}</footer>`:''}</section></div>`;m.hidden=false;setTimeout(()=>m.querySelector('button,input,textarea,select')?.focus(),10)}
function closeModal(){const m=$('#dialog');m.hidden=true;m.innerHTML=''}
function navItems(){return state.role==='officer'?[['overview','Overview','◫'],['applications','Applications','▤'],['review','Review queue','◎'],['activity','Agent activity','◷'],['reports','Reports','▧'],['settings','Settings','⚙']]:[['applicant-overview','Overview','◫'],['applicant-application','My application','▤'],['applicant-documents','Documents','⌑'],['applicant-verification','Verification','✓'],['applicant-requests','Requests','↗'],['applicant-help','Help','?']]}
function updateShell(){document.body.dataset.role=state.role;$('#nav').innerHTML=`<div class="nav-section">${state.role==='officer'?'WORKSPACE':'APPLICANT PORTAL'}</div>${navItems().map(([id,label,icon])=>`<button class="nav-item ${state.view===id?'active':''}" data-action="navigate" data-view="${id}"><span aria-hidden="true">${icon}</span>${label}${id==='review'&&state.data?`<b>${state.data.review_cases.length}</b>`:''}${id==='applicant-requests'&&state.applicant?`<b>${state.applicant.requests.filter(r=>r.status==='Open').length}</b>`:''}</button>`).join('')}`;
 const names={overview:'Overview',applications:'Applications',review:'Review queue',activity:'Agent activity',reports:'Reports',settings:'Settings','applicant-overview':'Overview','applicant-application':'My application','applicant-documents':'Documents','applicant-verification':'Verification','applicant-requests':'Requests','applicant-help':'Help'};
 $('#crumb').textContent=names[state.view]||'Overview';$('#role-label').textContent=state.role==='officer'?'Loan officer account':'Applicant account';const roleBadge=$('#account-role');if(roleBadge)roleBadge.textContent=state.role==='officer'?'Loan officer account':'Applicant account';
}
async function loadDashboard(){try{state.data=await api('/dashboard');state.loadError=null;const navCount=$('#nav-count'),reviewCount=$('#review-count');if(navCount)navCount.textContent=state.data.applications.length;if(reviewCount)reviewCount.textContent=state.data.review_cases.length;updateNotificationBadge()}catch(error){state.loadError=error}await render()}
function updateNotificationBadge(){let readAt=localStorage.getItem('ldv-read-at')||'';let count=(state.data?.applications||[]).flatMap(a=>a.events||[]).filter(e=>(e.agent==='Reviewer'||e.action==='Applicant request created')&&e.created_at>readAt).length;let dot=$('#notification-button .notification-dot');if(dot)dot.style.display=count?'block':'none';$('#notification-button')?.setAttribute('aria-label',count?`Notifications, ${count} unread items`:'Notifications')}
async function loadApplicant(id=state.applicantId){const owned=state.data?.applications||[];if(!id||!owned.some(a=>a.id===id))id=owned[0]?.id||'';if(!id){state.applicantId='';state.applicant=null;state.applicantError=null;localStorage.removeItem('ldv-applicant');updateShell();await render();return}state.applicantId=id;localStorage.setItem('ldv-applicant',id);try{state.applicant=await api('/applications/'+encodeURIComponent(id));state.applicantError=null}catch(error){state.applicant=null;state.applicantError=error}updateShell();await render()}
async function createShareInvite(id){try{const invite=await api(`/applications/${encodeURIComponent(id)}/share-invite`,{method:'POST'});showModal('Share this application',`<p>Give this one-time code to the loan officer who should review your application. It expires in 24 hours and can be accepted by one officer account.</p><label class="form-label">Invitation code<input class="input mono" id="share-code-display" value="${esc(invite.code)}" readonly onclick="this.select()"></label><p class="muted">The officer must sign in to their own LoanDocVerify account and enter this code under Applications.</p>`,`<button class="btn primary" data-action="close-modal">Done</button>`)}catch(e){toast(`Could not create invitation: ${e.message}`,'error')}}
function openAcceptInvite(){showModal('Link an applicant application','<p>Ask the applicant to share their one-time invitation code. Accepting it links the application to this loan officer account.</p><label class="form-label">Invitation code<input class="input mono" id="invite-code" maxlength="16" autocomplete="off" placeholder="16-character code"></label>','<button class="btn quiet" data-action="close-modal">Cancel</button><button class="btn primary" data-action="accept-invite-code">Link application</button>')}
async function acceptApplicationInvite(){const code=$('#invite-code')?.value.trim();if(!code){toast('Enter the invitation code.','error');$('#invite-code')?.focus();return}try{const result=await api('/application-invites/accept',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});closeModal();state.selected=null;state.view='applications';await updateData();await openCase(result.application_id);toast('Application linked to this officer account.')}catch(e){toast(e.message,'error')}}
function navigate(view){state.view=view;state.selected=null;state.notifications=false;state.page=1;updateShell();render();}
function pageHead(title,desc,action=''){return `<header class="page-head"><div><div class="eyebrow">${state.role==='officer'?'LOANDOCVERIFY · REVIEW OPERATIONS':'LOANDOCVERIFY · APPLICANT PORTAL'}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="head-actions">${action}</div>`:''}</header>`}
function stateBanner(text,kind='info'){return `<div class="inline-alert ${kind}"><span>${kind==='success'?'✓':kind==='warning'?'!':'i'}</span><div>${text}</div></div>`}
function metrics(items){return `<div class="metrics">${items.map((x,i)=>`<button class="metric" data-action="${x.action||'metric-noop'}" data-filter="${esc(x.filter||'')}" ${x.action?'':'aria-disabled="true"'}><span class="metric-icon">${x.icon}</span><span class="metric-label">${esc(x.label)}</span><strong class="metric-value">${esc(x.value)}</strong><small>${esc(x.note)}</small></button>`).join('')}</div>`}
function appTable(rows,compact=false){if(!rows.length)return empty('No applications linked yet','Ask the applicant to create a one-time invitation code and enter it here.','accept-invite','Link applicant application');return `<div class="table-scroll"><table class="data-table"><thead><tr>${[['applicant_name','Applicant'],['id','Application ID'],['loan_type','Loan type'],['requested_amount','Requested'],['created_at','Submitted'],['status','Status']].map(([key,label])=>`<th><button class="sort-button" data-action="sort" data-key="${key}">${label} ${state.sort===key?(state.sortDir>0?'↑':'↓'):'↕'}</button></th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.map(a=>`<tr data-action="open-case" data-id="${safeId(a.id)}" tabindex="0"><td><div class="person-cell"><span class="avatar">${initials(a.applicant_name)}</span><span><strong>${esc(a.applicant_name)}</strong><small>${esc(a.employer||'Applicant')}</small></span></div></td><td class="mono muted">${esc(a.id)}</td><td>${esc(a.loan_type)}</td><td class="numeric">${money(a.requested_amount)}</td><td>${humanDate(a.created_at)}</td><td>${badge(a.status)}</td><td><button class="link-btn" data-action="open-case" data-id="${safeId(a.id)}">Open case →</button></td></tr>`).join('')}</tbody></table></div>`}
function renderOverview(){if(state.loadError)return pageHead('Overview','Your officer workspace.')+apiError(state.loadError);const d=state.data, m=d.metrics;return `${pageHead('Good morning, Officer','Review your queue and pick up the cases that need attention.',`<button class="btn secondary" data-action="accept-invite">Link applicant application</button><button class="btn secondary" data-action="navigate" data-view="review">View review queue</button><button class="btn primary" data-action="focus-search">⌕ Search applications</button>`)}<div class="demo-banner"><span class="demo-badge">PRIVATE WORKSPACE</span><span>${m.total?`Your account contains ${m.total} loan application${m.total===1?'':'s'}.`:'Your workspace is ready. Link an applicant application using a one-time invitation code.'}</span><button class="link-btn" data-action="${m.total?'navigate':'accept-invite'}" ${m.total?'data-view="applications"':''}>${m.total?'Browse applications →':'Enter an applicant invitation →'}</button></div>${metrics([{label:'Total applications',value:m.total,note:'All submitted applications',icon:'▤',action:'filter-status',filter:'all'},{label:'In verification',value:m.processing,note:'Checks currently running',icon:'◷',action:'filter-status',filter:'Processing'},{label:'Needs review',value:m.review,note:'Officer action requested',icon:'◎',action:'filter-review',filter:'review'},{label:'Incomplete',value:m.incomplete,note:'Applicant evidence needed',icon:'⌑',action:'filter-status',filter:'Incomplete'},{label:'Verified checks',value:m.verified,note:'Checks complete; no approval implied',icon:'✓',action:'filter-status',filter:'Verified'}])}<div class="two-column"><section><div class="section-head"><div><h2>Priority review queue</h2><p>Cases with unresolved evidence or applicant follow-up</p></div><button class="link-btn" data-action="navigate" data-view="review">View queue →</button></div><div class="panel queue-list">${d.review_cases.length?d.review_cases.slice(0,4).map(r=>{const a=d.applications.find(x=>x.id===r.application_id);return `<article class="queue-card"><div class="priority-mark">!</div><div class="queue-main"><strong>${esc(r.applicant_name)}</strong><p>${esc(r.reason)}</p><small>${money(a?.requested_amount)} · ${esc(r.severity)} priority</small></div><button class="btn quiet" data-action="open-case" data-id="${safeId(r.application_id)}">Review case</button></article>`}).join(''):empty('Queue is clear','No cases need officer review right now.')}</div></section><section><div class="section-head"><div><h2>Latest agent activity</h2><p>Recorded tool actions from the sample cases</p></div><button class="link-btn" data-action="navigate" data-view="activity">View activity →</button></div><div class="panel activity-mini">${recentEvents(d.applications)}</div></section></div><section class="section-block"><div class="section-head"><div><h2>Recently submitted</h2><p>Open an application to inspect its evidence and next steps</p></div><button class="link-btn" data-action="navigate" data-view="applications">All applications →</button></div><div class="panel">${appTable(d.applications.slice(0,5),true)}</div></section>`}
function recentEvents(apps){const events=apps.flatMap(a=>(a.events||[]).map(e=>({...e,applicant:a.applicant_name,application_id:a.id}))).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5);return events.length?events.map(e=>`<div class="mini-event"><span class="event-dot ${statusClass(e.status)}"></span><div><strong>${esc(e.action)}</strong><p>${esc(e.applicant)} · ${esc(e.detail)}</p><time>${new Date(e.created_at).toLocaleString('en-IN',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'})}</time></div><button class="icon-btn" data-action="open-case" data-id="${safeId(e.application_id)}" aria-label="Open related case">↗</button></div>`).join(''):empty('No activity yet','Agent steps will appear when a verification run is started.')}
function filteredApps(){let apps=[...state.data.applications];if(state.view==='review')apps=apps.filter(a=>state.data.review_cases.some(r=>r.application_id===a.id));if(state.filter!=='All')apps=apps.filter(a=>a.status===state.filter);if(state.typeFilter&&state.typeFilter!=='All')apps=apps.filter(a=>a.loan_type===state.typeFilter);const q=state.query.toLowerCase();if(q)apps=apps.filter(a=>(a.applicant_name+' '+a.id+' '+a.loan_type).toLowerCase().includes(q));apps.sort((a,b)=>{let x=a[state.sort],y=b[state.sort];if(state.sort==='requested_amount'){x=Number(x);y=Number(y)}else{x=String(x||'').toLowerCase();y=String(y||'').toLowerCase()}return (x>y?1:x<y?-1:0)*state.sortDir});return apps}
function renderApplications(){if(state.loadError)return pageHead('Applications','Search and filter submitted applications.')+apiError(state.loadError);let all=filteredApps(),from=(state.page-1)*state.pageSize,rows=all.slice(from,from+state.pageSize);return `${pageHead(state.view==='review'?'Review queue':'Applications',state.view==='review'?'Triage cases with unresolved findings and applicant requests.':'Applications explicitly shared with your officer account.',`<button class="btn primary" data-action="accept-invite">Link applicant application</button>`)}<div class="filter-bar"><label class="searchbox"><span>⌕</span><input id="app-search" type="search" aria-label="Search by applicant or application ID" placeholder="Search applicant, ID, loan type" value="${esc(state.query)}"></label><label>Status <select id="app-filter"><option>All</option>${['Submitted','Processing','Incomplete','Needs clarification','Verified'].map(s=>`<option ${s===state.filter?'selected':''}>${s}</option>`).join('')}</select></label><label>Loan type <select id="type-filter"><option>All</option>${[...new Set(state.data.applications.map(a=>a.loan_type))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><button class="btn quiet" data-action="clear-filters">Clear filters</button><span class="results-count">${all.length} results</span></div><div class="panel">${appTable(rows)}</div><div class="pagination"><span>Showing ${all.length?from+1:0}–${Math.min(from+state.pageSize,all.length)} of ${all.length}</span><div><button class="btn quiet" data-action="page-prev" ${state.page<=1?'disabled':''}>← Previous</button><span>Page ${state.page} of ${Math.max(1,Math.ceil(all.length/state.pageSize))}</span><button class="btn quiet" data-action="page-next" ${state.page>=Math.ceil(all.length/state.pageSize)?'disabled':''}>Next →</button></div></div>`}
function renderReview(){return renderApplications()}
function profile(a){return `<div class="fact-grid"><div><small>Loan request</small><strong>${money(a.requested_amount)} · ${esc(a.loan_type)}</strong></div><div><small>Declared income</small><strong>${money(a.declared_income)} / month</strong></div><div><small>Employer</small><strong>${esc(a.employer||'Not provided')}</strong></div><div><small>Employment</small><strong>${esc(a.employment_type||'Not provided')}</strong></div><div><small>Email</small><strong>${esc(a.email||'Not provided')}</strong></div><div><small>Submitted</small><strong>${humanDate(a.created_at)}</strong></div></div>`}
function findingEvidenceBase(check){if(!check)return '<p>Select a finding to inspect its sources and next action.</p>';let e=check.evidence||{};let sourceIds=new Set();(e.sources||[]).forEach(x=>x.document_id&&sourceIds.add(x.document_id));(e.credits||[]).forEach(x=>x.document_id&&sourceIds.add(x.document_id));if(e.document_id)sourceIds.add(e.document_id);let sources=[...(e.sources||[]),...(e.credits||[]),...(e.payslip_sources||[]),...(e.duplicates||[]).map(x=>({...x,field:'file hash',value:x.sha256_prefix})),...(e.periods||[]).map(x=>({...x,field:'statement period',value:x.period}))];if(e.document_id)sources.push({document_id:e.document_id,document:e.document,field:e.field,value:e.value});if(e.payslips)sources.push(...e.payslips.map(x=>({...x,field:'net_salary'})));return `<div class="evidence-summary"><span class="confidence">${Math.round(check.confidence*100)}% extraction confidence</span><p>${esc(check.explanation)}</p></div>${sources.length?`<div class="evidence-list">${sources.map(s=>`<button class="evidence-source" data-action="preview-doc" data-id="${safeId(s.document_id)}"><span class="source-mark">▤</span><span><strong>${esc(s.document||s.file_name||'Source document')}</strong><small>${esc(s.field||'Source value')}: ${esc(s.value??s.net_salary??s.amount??'—')}</small></span><b>Open →</b></button>`).join('')}</div>`:''}<div class="next-action-card"><small>RECOMMENDED NEXT STEP</small><p>${esc(check.result==='Pass'?'Retain this as a completed document check.':check.result==='Unable to verify'?'Request a readable source before interpreting this field.':'Ask for clarification and let a reviewer assess the source documents.')}</p></div>`}
function findingEvidence(check){let base=findingEvidenceBase(check);if(!check||state.role!=='officer'||!state.selected)return base;let prior=state.selected.events.find(e=>e.action.startsWith('Finding marked:')&&e.detail.includes(`finding_id=${check.id}`));let decision=prior?.action.replace('Finding marked: ','');return `${base}<div class="review-decision"><strong>Officer assessment ${decision?badge(decision):''}</strong><small>Record a review action for this finding; it does not change lending eligibility.</small><div class="decision-buttons">${['Reviewed','Confirmed issue','Needs applicant clarification','Not applicable'].map(x=>`<button class="btn quiet" data-action="finding-decision" data-id="${safeId(check.id)}" data-decision="${x}">${esc(x)}</button>`).join('')}</div></div>`}
function checkCard(check){let id=check.id;return `<article class="check-card ${state.finding===id?'expanded':''}"><button class="check-summary" data-action="toggle-check" data-id="${safeId(id)}" aria-expanded="${state.finding===id}"><span class="check-symbol ${statusClass(check.result)}">${check.result==='Pass'?'✓':check.result==='Needs attention'?'!':'?'}</span><span class="check-title"><strong>${esc(check.check_type)}</strong><small>${esc(check.explanation)}</small></span><span class="confidence">${Math.round(check.confidence*100)}%</span><span class="result ${statusClass(check.result)}">${esc(check.result)}</span><span class="chevron">${state.finding===id?'⌃':'⌄'}</span></button>${state.finding===id?`<div class="check-detail">${findingEvidence(check)}</div>`:''}</article>`}
function docList(a){return a.documents.length?a.documents.map(d=>`<button class="doc-item ${state.docId===d.id?'selected':''}" data-action="select-doc" data-id="${safeId(d.id)}"><span class="doc-type-icon">${d.document_type==='Bank Statement'?'▧':'▤'}</span><span class="doc-label"><strong>${esc(d.file_name)}</strong><small>${esc(d.document_type)} · ${esc(d.processing_status)} · ${esc(d.quality_status)}</small></span>${badge(d.processing_status)}</button>`).join(''):empty('No documents','Upload evidence to begin a document review.')}
function documentPane(a){const doc=a.documents.find(d=>d.id===state.docId)||a.documents[0];if(doc)state.docId=doc.id;let extracted=doc?.extracted||{};return `<div class="viewer-pane"><div class="pane-heading"><div><strong>Document evidence</strong><small>${a.documents.length} uploaded</small></div><button class="icon-btn" data-action="preview-doc" data-id="${safeId(doc?.id)}" title="Open full preview">↗</button></div><div class="doc-picker">${docList(a)}</div>${doc?`<div class="document-display"><div class="document-display-head"><span>${esc(doc.file_name)}</span><button class="link-btn" data-action="open-file" data-id="${safeId(doc.id)}">Open original ↗</button></div><iframe title="Preview of ${esc(doc.file_name)}" src="/files/${encodeURIComponent(doc.storage_path.split(/[\\/]/).pop())}"></iframe><div class="extract-panel"><div class="section-label">EXTRACTED FIELDS <span>${esc(extracted.source||'Source unknown')}</span></div>${Object.entries(extracted).filter(([k,v])=>!['document_type','text_available','source','salary_credits','pan_format_valid'].includes(k)&&v!==null&&v!=='').slice(0,7).map(([k,v])=>`<div class="extract-row"><span>${esc(k.replaceAll('_',' '))}</span><strong>${esc(v)}</strong></div>`).join('')||'<p class="muted">No readable fields. Request a clearer file or OCR review.</p>'}<label class="form-label">Correct document type<select class="select" id="doc-type-${safeId(doc.id)}">${classificationOptions(doc.document_type,esc)}</select></label><div class="doc-actions"><button class="btn quiet" data-action="correct-doc" data-id="${safeId(doc.id)}">Save type</button><button class="btn danger" data-action="delete-doc" data-id="${safeId(doc.id)}">Remove</button></div></div></div>`:`<div class="preview-blank">Select or upload a document.</div>`}</div>`}
function workspace(a){let checks=a.checks||[],matching=checks.filter(c=>state.checkFilter==='All'||(state.checkFilter==='Passed'&&c.result==='Pass')||(state.checkFilter==='Needs attention'&&c.result==='Needs attention')||(state.checkFilter==='Pending'&&c.result==='Unable to verify'));return `<section class="review-workspace"><div class="workspace-header"><div><div class="eyebrow">APPLICATION · ${esc(a.id)}</div><h2>${esc(a.applicant_name)} <span>${badge(a.status)}</span></h2><p>${esc(a.loan_type)} · ${money(a.requested_amount)} requested · ${esc(a.employer||'Employer not provided')}</p></div><div class="actions"><button class="btn quiet" data-action="case-action" data-kind="request">Request documents</button><button class="btn quiet" data-action="case-action" data-kind="assign">Assign</button><button class="btn primary" data-action="case-action" data-kind="resolve">Resolve review</button></div></div><div class="workspace-tabs" role="tablist">${[['summary','Summary'],['documents','Documents'],['verification','Verification'],['activity','Agent activity'],['history','Review history']].map(([id,label])=>`<button role="tab" aria-selected="${state.caseTab===id}" class="workspace-tab ${state.caseTab===id?'active':''}" data-action="case-tab" data-tab="${id}">${label}</button>`).join('')}</div>${state.caseTab==='summary'?`<div class="workspace-grid"><div class="workspace-left">${documentPane(a)}</div><div class="workspace-center"><div class="pane-heading"><div><strong>Verification findings</strong><small>${checks.filter(c=>c.result==='Pass').length} passed · ${checks.filter(c=>c.result==='Needs attention').length} need attention</small></div><button class="btn quiet" data-action="run-verification" data-id="${safeId(a.id)}">${a.checks.length?'Run again':'Start verification'}</button></div><div class="filter-pills">${['All','Passed','Needs attention','Pending'].map(f=>`<button class="pill ${state.checkFilter===f?'active':''}" data-action="check-filter" data-filter="${f}">${f}</button>`).join('')}</div>${checks.length?matching.map(checkCard).join(''):empty('Verification not started','Start the agent run to classify documents and compare the extracted fields.','run-verification','Run verification')}</div><aside class="workspace-right"><div class="panel-title"><strong>Evidence & next step</strong><span class="ai-tag">● ASSISTIVE</span></div>${findingEvidence(checks.find(c=>c.id===state.finding))}<hr><div class="panel-title"><strong>Reviewer actions</strong></div><label class="form-label">Add a case note<textarea id="review-note" class="textarea" rows="3" placeholder="Record a concise evidence-based note…"></textarea></label><button class="btn secondary full-width" data-action="save-note" data-id="${safeId(a.id)}">Save note</button><div class="review-actions"><button class="btn quiet" data-action="case-action" data-kind="request">Request clarification</button><button class="btn quiet" data-action="case-action" data-kind="assign">Assign reviewer</button></div><div class="human-note">AI findings support review. They do not establish fraud or make a lending decision.</div></aside></div>`:state.caseTab==='documents'?`<div class="documents-workspace"><div class="documents-left">${documentPane(a)}</div><div class="documents-right"><div class="panel-title"><strong>Uploaded document checklist</strong><button class="btn primary" data-action="upload-docs" data-id="${safeId(a.id)}">＋ Upload</button></div>${a.documents.map(d=>`<div class="checklist-row"><span>${esc(d.document_type)}</span><strong>${esc(d.file_name)}</strong>${badge(d.quality_status)}</div>`).join('')}<div class="request-summary">Required in this demo: PAN, identity, salary slips, bank statement, employment proof.</div></div></div>`:state.caseTab==='verification'?`<div class="verification-list">${checks.length?matching.map(checkCard).join(''):empty('No findings yet','Run the verification tools to get evidence-linked checks.','run-verification','Run verification')}</div>`:state.caseTab==='activity'?`<div class="activity-page"><div class="recorded-run"><span class="ai-tag">RECORDED TOOL OUTPUTS</span><small>Persistent timeline · concise action summaries · no private prompts</small></div>${agentTimeline(a.events,true)}</div>`:`<div class="history-list">${a.reviews.map(r=>`<article class="history-card"><strong>Review case · ${esc(r.severity)} priority</strong><p>${esc(r.reason)}</p><small>${esc(r.status)} · ${humanDate(r.created_at)}</small>${r.resolution_notes?`<p>${esc(r.resolution_notes)}</p>`:''}</article>`).join('')}${a.events.filter(e=>e.agent==='Reviewer').map(e=>`<article class="history-card"><strong>${esc(e.action)}</strong><p>${esc(e.detail)}</p><small>${humanDate(e.created_at)}</small></article>`).join('')||'<p class="muted">Reviewer notes and decisions will appear here.</p>'}</div>`}</section>`}
function agentTimeline(events,all=false){let rows=all?events:[...events].slice(-6).reverse();if(state.playing&&state.playback.length)rows=state.playback.slice(0,state.playIndex+1);return `<div class="agent-run-head"><span class="ai-tag">${state.playing?'DETERMINISTIC DEMO PLAYBACK':'PERSISTED AGENT EVENTS'}</span><span>${rows.length} / ${events.length} actions</span>${state.playing?`<span class="running-indicator"><i></i> Replaying recorded results</span>`:''}</div><div class="agent-timeline">${rows.map((e,i)=>`<article class="agent-step ${state.playing&&i===rows.length-1?'current':''}"><span class="step-marker">${e.status==='Complete'?'✓':e.status==='Needs attention'?'!':'·'}</span><div class="step-copy"><div class="step-top"><strong>${esc(e.action)}</strong><span>${badge(e.status)}</span></div><p>${esc(e.detail)}</p><small>${esc(e.agent)} · ${new Date(e.created_at).toLocaleString('en-IN')}</small></div></article>`).join('')}</div>${events.length?`<button class="link-btn" data-action="navigate" data-view="activity">Open activity monitor →</button>`:empty('No recorded agent steps','Run verification to record classification, extraction, comparison and report actions.')}`}
function renderCase(a){if(!a)return '';return `<button class="back-link" data-action="back">← Back to ${state.view==='review'?'review queue':'applications'}</button>${workspace(a)}`}
function renderActivity(){if(state.loadError)return pageHead('Agent activity','Transparent summaries of document and verification tools.')+apiError(state.loadError);const events=state.data.applications.flatMap(a=>(a.events||[]).map(e=>({...e,applicant:a.applicant_name,application_id:a.id}))).sort((a,b)=>b.created_at.localeCompare(a.created_at));return `${pageHead('Agent activity','Recorded tool calls and outcomes. Expand a case for source evidence.',`<button class="btn secondary" data-action="navigate" data-view="applications">Open applications</button>`)}<div class="demo-banner"><span class="demo-badge">RECORDED OUTPUTS</span><span>Each action below comes from a persisted verification run. The case workspace can replay a completed run for demonstration.</span></div><div class="panel activity-feed">${events.length?events.map(e=>`<article class="feed-row"><span class="step-marker">${e.status==='Complete'?'✓':'!'}</span><div class="step-copy"><div class="step-top"><strong>${esc(e.action)}</strong>${badge(e.status)}</div><p>${esc(e.detail)}</p><small>${esc(e.agent)} · ${esc(e.applicant)} · ${new Date(e.created_at).toLocaleString('en-IN')}</small></div><button class="link-btn" data-action="open-case" data-id="${safeId(e.application_id)}">Open case →</button></article>`).join(''):empty('No recorded runs','Select a case and start verification to create activity records.','navigate','Browse applications')}</div>`}
function renderReports(rows=[]){if(state.loadError)return pageHead('Reports','Preview and export evidence reports.')+apiError(state.loadError);return `${pageHead('Verification reports','Reports are generated from persisted checks and source documents.',`<button class="btn secondary" data-action="navigate" data-view="applications">Open applications</button>`)}<div class="panel">${rows.map(a=>`<article class="report-row"><div class="report-icon">▧</div><div><strong>${esc(a.applicant_name)}</strong><p>${esc(a.application_id)} · ${esc(a.loan_type)} · ${a.check_count} checks</p></div>${badge(a.status)}<small>${a.generated_at?humanDate(a.generated_at):'Not generated'}</small><button class="btn quiet" data-action="preview-report" data-id="${safeId(a.application_id)}" ${a.check_count?'':'disabled title="Run verification before previewing"'}>Preview</button><button class="btn primary" data-action="download-report" data-id="${safeId(a.application_id)}" ${a.check_count?'':'disabled title="Run verification before exporting"'}>Download PDF</button></article>`).join('')||empty('No reports yet','Run verification on an application to generate its evidence report.','navigate','Browse applications')}</div>`}
function renderSettings(){return `${pageHead('Settings','Demo workspace controls and current rule configuration.')}<div class="settings-grid"><section class="panel settings-panel"><h2>Workspace preferences</h2><p>These settings are stored in this browser for the demo session.</p><label class="setting-row"><span><strong>Applicant request notifications</strong><small>Show a notice when new evidence is requested.</small></span><input type="checkbox" id="pref-requests" ${localStorage.getItem('ldv-pref-requests')!=='off'?'checked':''}></label><label class="setting-row"><span><strong>Reduced motion</strong><small>Limit animated interface transitions.</small></span><input type="checkbox" id="pref-motion" ${localStorage.getItem('ldv-pref-motion')==='on'?'checked':''}></label><button class="btn secondary" data-action="save-settings">Save preferences</button></section><section class="panel settings-panel"><h2>Verification demo rules</h2><p>Thresholds are examples for synthetic data and can be changed in <code>app.py</code>.</p><div class="rule-row"><span>Personal loan documents</span><strong>PAN · identity · 3 payslips · bank · employment</strong></div><div class="rule-row"><span>Education loan documents</span><strong>PAN · identity · 1 payslip · bank · employment</strong></div><div class="rule-row"><span>Income comparison threshold</span><strong>10% illustrative difference</strong></div><div class="rule-row"><span>Applicant messaging</span><strong>In-app only</strong></div></section></div>`}
function stepper(index){return `<div class="form-stepper">${['Personal','Loan details','Employment & income','Review'].map((x,i)=>`<div class="step ${i===index?'active':i<index?'complete':''}"><span>${i<index?'✓':i+1}</span><small>${x}</small></div>`).join('')}</div><div class="progress-track"><i style="width:${(index+1)*25}%"></i></div>`}
const formFields={0:[['applicant_name','Full legal name','text',true],['dob','Date of birth','date',true],['phone','Phone number','tel',true],['email','Email address','email',true]],1:[['loan_type','Loan type','select',true,['Personal Loan','Home Loan','Vehicle Loan','Education Loan']],['requested_amount','Requested amount (₹)','number',true],['purpose','Loan purpose','text',true]],2:[['employment_type','Employment type','select',true,['Salaried','Self-employed','Other']],['employer','Employer / business','text',false],['declared_income','Monthly income (₹)','number',true]]};
function formControl(f){const [key,label,type,required,options]=f, value=state.formData[key]??'';return `<label class="form-label">${label}${required?' *':''}${type==='select'?`<select class="input" name="${key}" ${required?'required':''}><option value="">Select…</option>${options.map(o=>`<option ${value===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input class="input" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${key==='requested_amount'||key==='declared_income'?'min="1"':''} ${key==='phone'?'minlength="7"':''}>`}<span class="field-error" data-error="${key}"></span></label>`}
function renderForm(){const i=state.formStep;return `${pageHead('Start a loan application','Complete each section. Your draft stays in this browser until you submit.')}${stepper(i)}<form id="application-wizard" class="panel wizard-panel" novalidate>${i<3?`<h2>${['Personal details','Loan details','Employment & income'][i]}</h2><p>${['Tell us who is applying.','Share what you need the loan for.','Help us understand your income sources.'][i]}</p><div class="form-grid">${formFields[i].map(formControl).join('')}</div>`:`<h2>Review your application</h2><p>Confirm these details before submitting.</p>${Object.entries({Personal:['applicant_name','dob','phone','email'],Loan:['loan_type','requested_amount','purpose'],Employment:['employment_type','employer','declared_income']}).map(([group,keys])=>`<section class="review-form-group"><div><strong>${group}</strong><button class="link-btn" type="button" data-action="form-edit" data-step="${group==='Personal'?0:group==='Loan'?1:2}">Edit</button></div>${keys.map(k=>`<div class="review-field"><span>${k.replaceAll('_',' ')}</span><b>${esc(k.includes('amount')||k.includes('income')?money(state.formData[k]):state.formData[k]||'—')}</b></div>`).join('')}</section>`).join('')}`}<div class="wizard-actions">${i>0?'<button class="btn quiet" type="button" data-action="form-back">← Back</button>':'<button class="btn quiet" type="button" data-action="applicant-home">Cancel</button>'}<span><button class="btn quiet" type="button" data-action="save-draft">Save draft</button> ${i<3?'<button class="btn primary" type="submit">Continue →</button>':'<button class="btn primary" type="button" data-action="submit-application">Submit application</button>'}</span></div></form>`}
function currentApplicant(){return state.applicant}
function applicantSelect(){return `<div class="app-select-row"><label class="app-select-label">Your applications<select id="applicant-select" class="select">${(state.data?.applications||[]).map(a=>`<option value="${safeId(a.id)}" ${a.id===state.applicantId?'selected':''}>${esc(a.applicant_name)} · ${esc(a.id.slice(0,8))}</option>`).join('')}</select></label><button class="btn secondary" data-action="new-application">＋ Start another application</button></div>`}
function applicantProgress(a){const complete=a.status==='Verified', stage=a.status==='Submitted'?0:a.status==='Processing'?1:a.documents.length?2:1;return `<div class="app-progress">${['Application submitted','Documents','Verification','Next step'].map((x,i)=>`<div class="app-progress-step ${i<stage||complete?'complete':''} ${i===stage&&!complete?'active':''}"><span>${i<stage||complete?'✓':i+1}</span><small>${x}</small></div>`).join('')}</div>`}
function applicantNext(a){let open=a.requests.filter(r=>r.status==='Open');if(open.length)return `<article class="next-action urgent"><div class="next-icon">!</div><div><span class="eyebrow">YOUR NEXT STEP</span><h3>${esc(open[0].requested_document)}</h3><p>${esc(open[0].reason)}</p></div><button class="btn primary" data-action="navigate" data-view="applicant-requests">View request →</button></article>`;if(!a.documents.length)return `<article class="next-action"><div class="next-icon">＋</div><div><span class="eyebrow">YOUR NEXT STEP</span><h3>Add your supporting documents</h3><p>Upload the documents listed in your checklist to begin verification.</p></div><button class="btn primary" data-action="navigate" data-view="applicant-documents">Upload documents →</button></article>`;return `<article class="next-action"><div class="next-icon">${a.status==='Verified'?'✓':'◷'}</div><div><span class="eyebrow">YOUR NEXT STEP</span><h3>${a.status==='Verified'?'Document checks are complete':'Your documents are with the review team'}</h3><p>${a.status==='Verified'?'A loan officer will review the evidence and contact you about what happens next.':'We’ll let you know if anything needs clarification.'}</p></div><button class="btn secondary" data-action="navigate" data-view="applicant-verification">See progress →</button></article>`}
function renderApplicantEmpty(){if(state.view==='applicant-help')return renderHelp();const pages={'applicant-overview':['Your workspace is ready','Create a loan application to see its documents, verification progress, and reviewer requests here.'],'applicant-application':['No application submitted','Start an application to review or update the details you provide.'],'applicant-documents':['No documents yet','Create an application first. You can then upload and manage its supporting documents.'],'applicant-verification':['No verification results yet','Create an application and add documents before verification findings can appear.'],'applicant-requests':['No requests yet','Requests and clarifications for your applications will appear here.']};const [title,detail]=pages[state.view]||pages['applicant-overview'];return `${pageHead(title,'Your applicant workspace.')}<section class="panel applicant-empty"><span class="empty-icon">▤</span><h2>${esc(title)}</h2><p>${esc(detail)}</p><button class="btn primary" data-action="new-application">＋ Start a loan application</button></section>`}
function renderApplicantOverview(a){if(state.applicantError)return pageHead('Your overview','Your application progress and next step.')+apiError(state.applicantError,'reload-applicant');return `${pageHead(`Welcome${a.applicant_name?', '+esc(a.applicant_name.split(' ')[0]):''}`,'Here’s where your application stands.',`<button class="btn primary" data-action="share-application" data-id="${safeId(a.id)}">Share with loan officer</button>`)}${applicantSelect()}<section class="share-invite-banner"><div class="share-invite-copy"><span class="share-invite-mark" aria-hidden="true">↗</span><div><strong>Ready to share this application?</strong><p>Generate a secure, one-time code for your loan officer to access this application.</p></div></div><button class="btn primary" data-action="share-application" data-id="${safeId(a.id)}">Share with loan officer</button></section><div class="applicant-overview-grid"><section class="panel current-app-card"><div class="app-card-top"><div><span class="eyebrow">CURRENT APPLICATION</span><h2>${esc(a.loan_type)}</h2><small class="mono">${esc(a.id)}</small></div>${badge(a.status)}</div><div class="app-stats"><div><small>Requested</small><strong>${money(a.requested_amount)}</strong></div><div><small>Submitted</small><strong>${humanDate(a.created_at)}</strong></div><div><small>Documents</small><strong>${a.documents.length} uploaded</strong></div></div>${applicantProgress(a)}${applicantNext(a)}<button class="link-btn" data-action="navigate" data-view="applicant-application">View application details →</button></section><aside><section class="panel applicant-card"><h3>Documents checklist</h3><p>${a.documents.length} files received</p>${personalLoanChecklist.map(item=>{const count=checklistCount(a,item.type);return `<div class="checklist-row"><span>${esc(item.label)}</span><strong>${checklistStatus(count,item.minimum)}</strong>${count>=item.minimum?'✓':count?'!':'·'}</div>`}).join('')}<button class="btn secondary full-width" data-action="navigate" data-view="applicant-documents">Manage documents</button></section><section class="panel applicant-card"><h3>Recent updates</h3>${a.events.slice(-3).reverse().map(e=>`<div class="app-update"><span>●</span><div><strong>${esc(e.action)}</strong><small>${esc(e.detail)}</small></div></div>`).join('')||'<p class="muted">Updates appear here as the review progresses.</p>'}</section></aside></div>`}
function renderApplicantApplication(a){return `${pageHead('My application','Review the details you submitted.',`<button class="btn primary" data-action="share-application" data-id="${safeId(a.id)}">Share with loan officer</button>`)}${applicantSelect()}<div class="panel applicant-card"><div class="app-card-top"><div><span class="eyebrow">${esc(a.id)}</span><h2>${esc(a.applicant_name)}</h2></div>${badge(a.status)}</div>${profile(a)}<div class="notice-box">You can ask the loan officer to correct application details. Changes are recorded in the review history.</div><button class="btn secondary" data-action="edit-application" data-id="${safeId(a.id)}">Edit my details</button></div>`}
function uploadSection(a){return `<section class="upload-zone" id="upload-zone"><input type="file" id="upload-input" multiple accept=".pdf,.jpg,.jpeg,.png,.txt,.csv" hidden><span class="upload-mark">↑</span><strong>Drag files here or <button class="link-btn" data-action="browse-files">browse files</button></strong><small>PDF, JPG, PNG · up to 10 MB per file · Synthetic data only</small><p>Documents stay on this local demo workspace. Do not upload real identity or bank records.</p></section>${state.uploadProgress!==null?`<div class="upload-progress"><span>Uploading ${state.uploadProgress}%</span><i><b style="width:${state.uploadProgress}%"></b></i></div>`:''}`}
function renderApplicantDocuments(a){return `${pageHead('Your documents','Upload, preview and manage the evidence for this application.',`<button class="btn primary" data-action="browse-files">＋ Upload documents</button>`)}${applicantSelect()}<div class="document-summary">${metrics([{label:'Files received',value:a.documents.length,note:'Stored for this application',icon:'▤'},{label:'Need attention',value:a.documents.filter(d=>d.quality_status!=='Readable').length,note:'Unreadable or duplicate',icon:'!'},{label:'Open requests',value:a.requests.filter(r=>r.status==='Open').length,note:'Items requested by the reviewer',icon:'↗'}])}</div>${uploadSection(a)}<section class="section-block"><div class="section-head"><div><h2>Uploaded files</h2><p>Uploaded, processing and verification states are separate.</p></div></div><div class="doc-grid">${a.documents.map(d=>`<article class="panel doc-card"><div class="doc-card-top"><span class="doc-type-icon">▤</span>${badge(d.quality_status)}</div><strong>${esc(d.file_name)}</strong><small>${esc(d.document_type)} · Uploaded · ${esc(d.processing_status)} · ${esc(d.quality_status)} · ${(d.size_bytes/1024).toFixed(1)} KB</small>${`<label class="form-label">Classification<select class="select" id="doc-type-${safeId(d.id)}">${classificationOptions(d.document_type,esc)}</select></label><button class="link-btn" data-action="correct-doc" data-id="${safeId(d.id)}">Save classification</button>`}<div class="doc-card-actions"><button class="link-btn" data-action="preview-doc" data-id="${safeId(d.id)}">Preview</button><button class="link-btn" data-action="replace-doc" data-id="${safeId(d.id)}">Replace</button><button class="link-btn danger-text" data-action="delete-doc" data-id="${safeId(d.id)}">Remove</button></div></article>`).join('')||empty('No documents yet','Choose files above to add them to your application.','browse-files','Choose files')}</div></section><section class="panel checklist-panel"><h2>Personal loan document checklist</h2>${personalLoanChecklist.map(item=>{const count=checklistCount(a,item.type);return `<div class="checklist-row"><span>${esc(item.label)}</span><strong>${checklistStatus(count,item.minimum)}</strong></div>`}).join('')}</section>`}
function renderApplicantVerification(a){let checks=a.checks||[];return `${pageHead('Verification results','Review the checks completed on the documents you submitted.')}${applicantSelect()}<div class="trust-banner">Document checks assist the review team. A finding is not a fraud determination or a lending decision.</div>${metrics([{label:'Checks passed',value:checks.filter(x=>x.result==='Pass').length,note:'Evidence matched configured checks',icon:'✓'},{label:'Needs attention',value:checks.filter(x=>x.result==='Needs attention').length,note:'Reviewer or applicant follow-up',icon:'!'},{label:'Unable to verify',value:checks.filter(x=>x.result==='Unable to verify').length,note:'More readable evidence may be needed',icon:'?'}])}<div class="filter-pills page-filter">${['All','Passed','Needs attention','Pending'].map(f=>`<button class="pill ${state.checkFilter===f?'active':''}" data-action="check-filter" data-filter="${f}">${f}</button>`).join('')}</div><div class="panel result-list">${checks.length?checks.filter(c=>state.checkFilter==='All'||state.checkFilter==='Passed'&&c.result==='Pass'||state.checkFilter==='Needs attention'&&c.result==='Needs attention'||state.checkFilter==='Pending'&&c.result==='Unable to verify').map(checkCard).join(''):empty('Verification has not started','Your documents are stored. The reviewer will start the checks when ready.')}</div>`}
function renderApplicantRequests(a){let requests=a.requests||[];return `${pageHead('Requests & clarifications','Respond to outstanding document requests and review previous messages.')}${applicantSelect()}<div class="request-tabs">${['Open','Submitted','All'].map(t=>`<button class="pill ${state.requestTab===t?'active':''}" data-action="request-filter" data-filter="${t}">${t}</button>`).join('')}</div><div class="request-list">${requests.filter(r=>state.requestTab==='All'||state.requestTab==='Open'&&r.status==='Open'||state.requestTab==='Submitted'&&r.status!=='Open').map(r=>`<article class="panel request-card"><div class="request-card-heading"><span class="request-icon">↗</span><div><strong>${esc(r.requested_document)}</strong><small>Requested ${humanDate(r.created_at)}</small></div>${badge(r.status)}</div><p>${esc(r.reason)}</p>${r.status==='Open'?`<label class="form-label">Your response<textarea id="response-${safeId(r.id)}" class="textarea" rows="3" placeholder="Add a message for the reviewer…"></textarea></label><div class="request-actions"><label class="btn quiet file-button">＋ Attach supporting file<input type="file" id="response-file-${safeId(r.id)}" hidden accept=".pdf,.jpg,.jpeg,.png,.txt,.csv"></label><button class="btn primary" data-action="respond-request" data-id="${safeId(r.id)}">Submit response</button></div>`:`<p class="muted">Your response has been sent. The review team can now continue.</p>`}</article>`).join('')||empty('No requests in this view','New document or clarification requests will appear here.')}</div><section class="panel message-thread"><h2>Recent messages</h2>${a.events.filter(e=>['Applicant','Reviewer'].includes(e.agent)).map(e=>`<div class="thread-message"><small>${esc(e.agent)} · ${humanDate(e.created_at)}</small><p>${esc(e.detail)}</p></div>`).join('')||'<p class="muted">There are no messages yet.</p>'}</section>`}
function renderHelp(){return `${pageHead('Help & guidance','A few answers to common questions about the document review process.')}<div class="help-layout"><div class="panel help-card"><span class="help-symbol">1</span><h2>What happens after I upload?</h2><p>Documents are classified and checked for readable information. A reviewer compares the extracted values across your application and supporting files.</p></div><div class="panel help-card"><span class="help-symbol">2</span><h2>Why was I asked to clarify?</h2><p>Some values differ or a requested period is missing. Differences can have several explanations; a reviewer may ask you to provide context or more evidence.</p></div><div class="panel help-card"><span class="help-symbol">3</span><h2>Does “verified” mean approved?</h2><p>No. It means configured document checks are complete. An authorized loan officer makes every lending decision.</p></div></div><div class="notice-box">This local demonstration uses synthetic data. Do not upload real PAN, Aadhaar, bank statements or applicant data.</div><button class="btn secondary" data-action="contact-support">Contact demo support</button>`}
function applicantRoute(a){if(!a)return pageHead('Applicant portal','Your application progress.')+apiError(state.applicantError||'Select an application to continue.');switch(state.view){case'applicant-overview':return renderApplicantOverview(a);case'applicant-application':return renderApplicantApplication(a);case'applicant-documents':return renderApplicantDocuments(a);case'applicant-verification':return renderApplicantVerification(a);case'applicant-requests':return renderApplicantRequests(a);case'applicant-help':return renderHelp();default:return renderApplicantOverview(a)}}
async function render(){const content=$('#content');content.innerHTML=loading();if(state.view==='new-application'){content.innerHTML=renderForm();wireDynamicInputs();return}if(state.role==='officer'&&state.selected){content.innerHTML=renderCase(state.selected);return}if(state.role==='applicant'){if(!state.applicant&&!state.applicantError){const owned=state.data?.applications||[],saved=localStorage.getItem('ldv-applicant'),chosen=owned.find(a=>a.id===state.applicantId)||owned.find(a=>a.id===saved)||owned[0];if(chosen){await loadApplicant(chosen.id);return}content.innerHTML=state.loadError?pageHead('Applicant portal','Your application progress.')+apiError(state.loadError,'retry'):renderApplicantEmpty();wireDynamicInputs();return}if(state.applicantError)content.innerHTML=pageHead('Your application','We couldn’t load this application.')+apiError(state.applicantError,'reload-applicant');else content.innerHTML=applicantRoute(state.applicant);wireDynamicInputs();return}if(state.loadError){content.innerHTML=pageHead('Workspace','')+apiError(state.loadError);return}if(!state.data){await loadDashboard();return}if(state.view==='overview')content.innerHTML=renderOverview();else if(state.view==='applications'||state.view==='review')content.innerHTML=renderApplications();else if(state.view==='activity')content.innerHTML=renderActivity();else if(state.view==='reports'){try{content.innerHTML=renderReports(await api('/admin/reports'))}catch(e){state.loadError=e;content.innerHTML=renderReports()}}else if(state.view==='settings')content.innerHTML=renderSettings();else content.innerHTML=renderOverview();wireDynamicInputs()}
function wireDynamicInputs(){const search=$('#app-search');if(search)search.oninput=()=>{state.query=search.value;state.page=1;const pos=search.selectionStart;render();const replacement=$('#app-search');replacement?.focus();replacement?.setSelectionRange(pos,pos)};$('#app-filter')?.addEventListener('change',e=>{state.filter=e.target.value;state.page=1;render()});$('#type-filter')?.addEventListener('change',e=>{state.typeFilter=e.target.value;state.page=1;render()});const zone=$('#upload-zone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag-over')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag-over');handleUpload(e.dataTransfer.files)});$('#upload-input').onchange=e=>handleUpload(e.target.files)}$('#applicant-select')?.addEventListener('change',e=>loadApplicant(e.target.value));$('#pref-motion')?.addEventListener('change',e=>document.body.classList.toggle('reduce-motion',e.target.checked))}

function updateData(){return loadDashboard()}
function setRole(role){if(role!==state.user?.role){toast('Sign out and use the other account to change workspace roles.','error');return}state.role=role;state.view=role==='officer'?'overview':'applicant-overview';state.selected=null;updateShell();if(role==='applicant')loadApplicant();else loadDashboard()}
async function openCase(id){try{state.selected=await api('/applications/'+encodeURIComponent(id));state.finding=state.selected.checks.find(c=>c.result==='Needs attention')?.id||state.selected.checks[0]?.id||null;state.docId=state.selected.documents[0]?.id||null;state.caseTab='summary';state.playing=false;updateShell();await render()}catch(e){toast(e.message,'error')}}
async function runVerification(id){const button=$(`[data-action="run-verification"][data-id="${CSS.escape(id)}"]`);if(button){button.disabled=true;button.textContent='Running tools…'}try{const result=await api(`/applications/${encodeURIComponent(id)}/verification/start`,{method:'POST'});if(!result.checks)throw new Error('The verification returned no check results.');state.selected=await api('/applications/'+encodeURIComponent(id));state.finding=state.selected.checks.find(c=>c.result==='Needs attention')?.id||state.selected.checks[0]?.id;state.docId=state.selected.documents[0]?.id||null;state.playback=result.events||[];state.playIndex=0;state.playing=state.playback.length>0;await updateData();if(state.role==='applicant')state.view='applicant-verification';if(state.role==='officer')state.selected=await api('/applications/'+encodeURIComponent(id));updateShell();await render();toast(`Recorded ${result.checks.length} evidence-linked checks.`);if(state.playing){clearInterval(state.playTimer);state.playTimer=setInterval(()=>{if(state.playIndex<state.playback.length-1){state.playIndex++;if(state.selected)render()}else{clearInterval(state.playTimer);state.playing=false;if(state.selected)render()}},500)}}catch(e){toast(`Verification did not complete: ${e.message}`,'error');if(button){button.disabled=false;button.textContent='Retry verification'}}}
function previewDoc(id){const d=state.selected?.documents.find(x=>x.id===id)||state.applicant?.documents.find(x=>x.id===id);if(!d){toast('Document not found. Refresh the application and try again.','error');return}state.docId=id;const file='/files/'+encodeURIComponent(d.storage_path.split(/[\\/]/).pop()),ext=d.file_name.split('.').pop().toLowerCase();const body=ext==='pdf'?`<iframe class="modal-doc" title="${esc(d.file_name)}" src="${file}"></iframe>`:ext==='png'||ext==='jpg'||ext==='jpeg'?`<img class="modal-image" alt="Preview of ${esc(d.file_name)}" src="${file}">`:`<iframe class="modal-doc" title="${esc(d.file_name)}" src="${file}"></iframe>`;showModal(d.file_name,`<p class="muted">${esc(d.document_type)} · ${esc(d.quality_status)} · Synthetic demo file</p>${body}<div class="extract-panel">${Object.entries(d.extracted||{}).filter(([k,v])=>v!==null&&v!==''&&!['text_available','source'].includes(k)).map(([k,v])=>`<div class="extract-row"><span>${esc(k.replaceAll('_',' '))}</span><strong>${esc(Array.isArray(v)?JSON.stringify(v):v)}</strong></div>`).join('')}</div>`,`<a class="btn secondary" href="${file}" download>Download original</a><button class="btn primary" data-action="close-modal">Done</button>`)}
function confirmation(title,description,form,submitLabel,action,extra=''){showModal(title,`<p>${description}</p>${form}`,`<button class="btn quiet" data-action="close-modal">Cancel</button><button class="btn primary" data-action="${action}">${submitLabel}</button>${extra}`)}
function findingDecisionDialog(id,decision){const check=(state.selected?.checks||[]).find(x=>x.id===id);if(!check)return;state.pendingFinding={id,decision};let needsNote=['Confirmed issue','Not applicable'].includes(decision);showModal('Record finding assessment',`<p><strong>${esc(check.check_type)}</strong> · ${esc(decision)}</p><p>This is a human review action saved to the case history. It does not decide loan eligibility.</p><label class="form-label">Reviewer note${needsNote?' *':''}<textarea id="finding-review-note" class="textarea" rows="3" placeholder="Summarize your reasoning from the cited evidence…"></textarea></label>`,`<button class="btn quiet" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-finding-review">Save assessment</button>`)}
async function submitFindingReview(){let pending=state.pendingFinding;if(!pending||!state.selected)return;let note=$('#finding-review-note')?.value.trim()||'',check=state.selected.checks.find(x=>x.id===pending.id);if(['Confirmed issue','Not applicable'].includes(pending.decision)&&!note){toast('Add a reviewer note for this assessment.','error');return}try{await api(`/applications/${encodeURIComponent(state.selected.id)}/review/finding`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({finding_id:pending.id,decision:pending.decision,note})});if(pending.decision==='Needs applicant clarification')await api(`/applications/${encodeURIComponent(state.selected.id)}/requests`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_type:`Clarification: ${check?.check_type||'verification finding'}`,reason:note||check?.explanation||'Please clarify this finding.'})});let id=state.selected.id;state.pendingFinding=null;closeModal();await openCase(id);toast('Finding assessment saved to the review history.')}catch(e){toast(`Assessment wasn’t saved: ${e.message}`,'error')}}
function onCaseAction(kind){if(!state.selected)return;const a=state.selected;if(kind==='request'){confirmation('Request documents','Tell the applicant what to provide and why. The request will appear in their Requests page.',`<label class="form-label">Document / clarification type<input id="request-type" class="input" required value="Additional evidence"></label><label class="form-label">Reason<textarea id="request-reason" class="textarea" rows="4" required placeholder="Explain which information needs clarification."></textarea></label>`,'Send request','submit-request');return}if(kind==='assign'){confirmation('Assign reviewer','Choose a reviewer for this synthetic demo case.',`<label class="form-label">Reviewer<select id="reviewer-name" class="input"><option>Loan Officer</option><option>Senior Reviewer</option><option>Verification Team</option></select></label>`,'Assign case','submit-assign');return}if(kind==='resolve'){confirmation('Resolve review case','Close the officer review after recording the resolution. This does not approve or decline the loan.',`<label class="form-label">Resolution<select id="resolution-type" class="input"><option>Evidence reviewed; no further document action</option><option>Applicant clarification received; continue review</option><option>Escalated for additional human review</option><option>Not applicable</option></select></label><label class="form-label">Reviewer note (optional)<textarea id="resolution-note" class="textarea" rows="3"></textarea></label>`,'Confirm resolution','submit-resolve');return}}
async function caseMutation(action,data){let id=state.selected?.id;if(!id)return;try{await api(`/applications/${encodeURIComponent(id)}/review/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();await openCase(id);toast(action==='note'?'Reviewer note saved.':'Reviewer assignment saved.')}catch(e){toast(e.message,'error')}}
function confirmDelete(docId){const d=(state.selected?.documents||state.applicant?.documents||[]).find(x=>x.id===docId);if(!d)return;confirmation('Remove this document?',`<strong>${esc(d.file_name)}</strong> will be removed from this demo application. This cannot be undone.`,`<p>Removing a submitted source can change verification results. Rerun checks after replacing it.</p>`,'Remove document','confirm-delete',`<input type="hidden" id="delete-doc-id" value="${safeId(docId)}">`)}
async function removeDoc(id){try{await api('/documents/'+encodeURIComponent(id),{method:'DELETE'});closeModal();toast('Document removed.');if(state.selected)await openCase(state.selected.id);if(state.applicant)await loadApplicant()}catch(e){toast(e.message,'error')}}
async function handleUpload(files){if(!files?.length)return;const allowed=['pdf','jpg','jpeg','png','txt','csv'];for(const f of files){const ext=f.name.split('.').pop().toLowerCase();if(!allowed.includes(ext)){toast(`${f.name}: unsupported file type.`,'error');return}if(f.size>10*1024*1024){toast(`${f.name}: file exceeds the 10 MB limit.`,'error');return}}const id=state.applicant?.id||state.selected?.id;if(!id){toast('Select an application before uploading.','error');return}const replacing=state.replaceDoc;let uploaded=false;state.uploadProgress=0;render();try{const res=await uploadFiles(`/applications/${encodeURIComponent(id)}/documents`,files,n=>{state.uploadProgress=n;const progress=$('.upload-progress b');if(progress)progress.style.width=n+'%'});uploaded=true;state.uploadProgress=null;if(replacing){await api('/documents/'+encodeURIComponent(replacing),{method:'DELETE'});state.replaceDoc=null}toast(`${res.uploaded.length} file${res.uploaded.length===1?'':'s'} uploaded and classified${replacing?'; previous file replaced':''}.`);if(state.role==='applicant')await loadApplicant(id);else await openCase(id)}catch(e){state.uploadProgress=null;if(uploaded){state.replaceDoc=null;toast(`The new file uploaded, but the previous document could not be removed: ${e.message}`,'error');if(state.role==='applicant')await loadApplicant(id);else await openCase(id)}else{state.replaceDoc=null;render();toast(`Upload failed: ${e.message}`,'error')}}}

function modalWizard(){state.formStep=0;state.formOrigin=state.editingId?'applicant-application':'applicant-overview';if(!state.editingId)state.formData=JSON.parse(localStorage.getItem('ldv-draft')||'{}');navigate('new-application')}
async function submitWizard(){const d={...state.formData,requested_amount:Number(state.formData.requested_amount),declared_income:Number(state.formData.declared_income)};try{let editing=!!state.editingId;let a=editing?await api(`/applications/${encodeURIComponent(state.editingId)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}):await api('/applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});state.editingId=null;localStorage.removeItem('ldv-draft');state.applicantId=a.id;localStorage.setItem('ldv-applicant',a.id);state.view='applicant-overview';await loadDashboard();await loadApplicant(a.id);showModal(editing?'Details updated':'Application submitted',`<div class="success-mark">✓</div><p>${editing?'Your details were updated for':'Your application'} <strong>${esc(a.id)}</strong>${editing?'.':' has been created. Add the supporting documents listed in your checklist.'}</p>`,`<button class="btn primary" data-action="close-modal">Go to my overview</button>`);toast(editing?'Application details updated.':'Application submitted successfully.')}catch(e){toast(`We couldn’t submit this application: ${e.message}`,'error')}}
async function respondRequest(id){const message=$(`#response-${CSS.escape(id)}`)?.value.trim();const file=$(`#response-file-${CSS.escape(id)}`)?.files[0];if(!message&&!file){toast('Add a response or supporting document before submitting.','error');return}try{if(file)await uploadFiles(`/applications/${encodeURIComponent(state.applicant.id)}/documents`,[file]);await api(`/applications/${encodeURIComponent(state.applicant.id)}/requests/${encodeURIComponent(id)}/respond`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:message||'Supporting document uploaded.'})});await loadApplicant();toast('Your response was sent to the review team.')}catch(e){toast(`Response was not submitted: ${e.message}`,'error')}}
async function correctDoc(id){const type=$(`#doc-type-${CSS.escape(id)}`)?.value;if(!type){toast('Choose one of the checklist classifications before saving.','error');return}try{await api('/documents/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_type:type})});toast('Document type updated. Run verification again to refresh findings.');if(state.selected)await openCase(state.selected.id);if(state.applicant)await loadApplicant()}catch(e){toast(e.message,'error')}}
function saveDraft(){for(const input of $('#application-wizard').querySelectorAll('input,select'))state.formData[input.name]=input.value;localStorage.setItem('ldv-draft',JSON.stringify(state.formData));toast('Draft saved in this browser.')}
function validateStep(form){let okay=true;for(const f of form.querySelectorAll('[required]')){let wrap=f.closest('.form-label'),err=wrap?.querySelector('.field-error');let issue=!f.value?'This field is required.':f.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.value)?'Enter a valid email address.':f.type==='number'&&Number(f.value)<=0?'Enter an amount greater than zero.':f.name==='phone'&&f.value.replace(/\D/g,'').length<7?'Enter a valid phone number.':'';if(err)err.textContent=issue;if(issue)okay=false}return okay}
function handleFormSubmit(form){if(!validateStep(form))return toast('Check the highlighted fields and try again.','error');const data=Object.fromEntries(new FormData(form));Object.assign(state.formData,data);if(state.formStep<3){state.formStep++;render()}else submitWizard()}
function focusCase(){const note=$('#review-note');if(note){note.focus();return}const search=$('#app-search');navigate('applications');setTimeout(()=>$('#app-search')?.focus(),0)}
function handleClick(e){const t=e.target.closest('[data-action]');if(!t)return;const action=t.dataset.action,id=t.dataset.id,view=t.dataset.view;
 switch(action){case'signout':signOut();return;case'navigate':state.view=view;state.selected=null;state.page=1;state.loadError=null;updateShell();render();return;case'open-case':e.preventDefault();openCase(id);return;case'new-application':state.editingId=null;modalWizard();return;case'back':state.selected=null;render();return;case'run-verification':runVerification(id);return;case'case-tab':state.caseTab=t.dataset.tab;state.finding=null;render();return;case'toggle-check':state.finding=state.finding===id?null:id;render();return;case'check-filter':state.checkFilter=t.dataset.filter;render();return;case'open-file':{let d=state.selected?.documents.find(x=>x.id===id)||state.applicant?.documents.find(x=>x.id===id);if(d)window.open('/files/'+encodeURIComponent(d.storage_path.split(/[\\/]/).pop()),'_blank','noopener');return}case'preview-doc':previewDoc(id);return;case'select-doc':state.docId=id;render();return;case'browse-files':$('#upload-input')?.click();return;case'upload-docs':$('#upload-input')?.click();return;case'delete-doc':confirmDelete(id);return;case'confirm-delete':removeDoc($('#delete-doc-id').value);return;case'replace-doc':state.replaceDoc=id;$('#upload-input')?.click();return;case'correct-doc':correctDoc(id);return;case'request-filter':state.requestTab=t.dataset.filter;render();return;case'respond-request':respondRequest(id);return;case'case-action':onCaseAction(t.dataset.kind);return;case'save-note':{let note=$('#review-note').value.trim();if(!note){toast('Write a note before saving.','error');return}caseMutation('note',{note});return}case'submit-request':{let type=$('#request-type').value.trim(),reason=$('#request-reason').value.trim();if(!type||!reason){toast('Enter both a document type and a reason.','error');return}api(`/applications/${encodeURIComponent(state.selected.id)}/requests`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_type:type,reason})}).then(async()=>{closeModal();await openCase(state.selected.id);toast('Applicant request sent.')}).catch(x=>toast(x.message,'error'));return}case'submit-assign':case'submit-resolve':{if(action==='submit-assign'){caseMutation('assign',{reviewer:$('#reviewer-name').value});return}const review=(state.selected.reviews||[]).find(x=>x.status==='Open');if(!review){toast('No open review case is attached to this application.','error');closeModal();return}api(`/admin/review-cases/${encodeURIComponent(review.id)}/resolve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:`${$('#resolution-type').value}${$('#resolution-note').value.trim()?': '+$('#resolution-note').value.trim():''}`})}).then(async()=>{let caseId=state.selected.id;closeModal();await updateData();await openCase(caseId);toast('Review case closed. Lending decision remains with an authorized officer.')}).catch(x=>toast(x.message,'error'));return}case'close-modal':closeModal();return;case'modal-backdrop':if(e.target===t)closeModal();return;case'preview-report':window.open(`/api/applications/${encodeURIComponent(id)}/verification/report.pdf`,'_blank','noopener');return;case'download-report':{const a=document.createElement('a');a.href=`/api/applications/${encodeURIComponent(id)}/verification/report.pdf`;a.download=`LoanDocVerify-${id}.pdf`;a.click();return}case'sort':if(state.sort===t.dataset.key)state.sortDir*=-1;else{state.sort=t.dataset.key;state.sortDir=1}render();return;case'clear-filters':state.filter='All';state.query='';state.typeFilter='All';state.page=1;render();return;case'page-prev':state.page=Math.max(1,state.page-1);render();return;case'page-next':state.page++;render();return;case'filter-status':state.filter=t.dataset.filter==='all'?'All':t.dataset.filter;state.view='applications';render();return;case'filter-review':state.view='review';render();return;case'focus-search':focusCase();return;case'metric-noop':toast('This is a summary card. Use the application filters below.');return;case'form-back':saveFormState();state.formStep--;render();return;case'form-edit':saveFormState();state.formStep=Number(t.dataset.step);render();return;case'save-draft':saveDraft();return;case'submit-application':saveFormState();if(validateStep($('#application-wizard')))submitWizard();else toast('Complete any required fields before submitting.','error');return;case'applicant-home':state.role='applicant';state.view='applicant-overview';updateShell();loadApplicant();return;case'edit-application':{let data=state.applicant;state.editingId=data.id;state.formData={applicant_name:data.applicant_name,dob:data.dob,phone:data.phone,email:data.email,loan_type:data.loan_type,requested_amount:data.requested_amount,purpose:data.purpose,employment_type:data.employment_type,employer:data.employer,declared_income:data.declared_income};modalWizard();return}case'save-settings':localStorage.setItem('ldv-pref-requests',$('#pref-requests').checked?'on':'off');localStorage.setItem('ldv-pref-motion',$('#pref-motion').checked?'on':'off');document.body.classList.toggle('reduce-motion',$('#pref-motion').checked);toast('Preferences saved in this browser.');return;case'contact-support':showModal('Contact demo support','<p>This local demo has no connected support inbox. Add your question to the review notes so it remains with the application.</p>','<button class="btn primary" data-action="close-modal">Understood</button>');return;case'reload-applicant':loadApplicant();return;case'retry':state.loadError=null;loadDashboard();return;case'toggle-notifications':state.notifications=!state.notifications;renderNotificationPanel();return;case'mark-read':localStorage.setItem('ldv-read-at',new Date().toISOString());renderNotificationPanel();return;case'select-notification':state.notifications=false;openCase(id);return;case'toggle-mobile':document.body.classList.toggle('nav-open');return;case'share-application':createShareInvite(id);return;case'accept-invite':openAcceptInvite();return;case'accept-invite-code':acceptApplicationInvite();return;case'close-notifications':state.notifications=false;renderNotificationPanel();return;case'retry-upload':$('#upload-input')?.click();return;default:return}}
function saveFormState(){const f=$('#application-wizard');if(!f)return;for(const input of f.querySelectorAll('input,select'))state.formData[input.name]=input.value;localStorage.setItem('ldv-draft',JSON.stringify(state.formData))}
function renderNotificationPanel(){updateNotificationBadge();const box=$('#notification-panel');if(!state.notifications){box.hidden=true;return}let readAt=localStorage.getItem('ldv-read-at')||'';let items=(state.data?.applications||[]).flatMap(a=>(a.events||[]).map(e=>({...e,applicant:a.applicant_name,application_id:a.id}))).filter(x=>(x.agent==='Reviewer'||x.action==='Applicant request created')&&x.created_at>readAt).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,6);box.hidden=false;box.innerHTML=`<div class="notification-head"><strong>Notifications</strong><button class="link-btn" data-action="mark-read">Mark all read</button><button class="icon-btn" data-action="close-notifications">×</button></div>${items.length?items.map(n=>`<button class="notification-item" data-action="select-notification" data-id="${safeId(n.application_id)}"><strong>${esc(n.action)}</strong><small>${esc(n.applicant)} · ${esc(n.detail)}</small><time>${humanDate(n.created_at)}</time></button>`).join(''):'<div class="empty-notifications">No new notifications.</div>'}`}

function bindGlobal(){document.addEventListener('click',e=>{const cancel=e.target.closest('[data-action="applicant-home"]');if(cancel){e.preventDefault();e.stopImmediatePropagation();state.editingId=null;state.role=state.user?.role||'applicant';state.view=state.formOrigin;updateShell();render();return}const t=e.target.closest('[data-action="finding-decision"]');if(t){e.preventDefault();e.stopImmediatePropagation();findingDecisionDialog(t.dataset.id,t.dataset.decision)}},true);document.addEventListener('click',e=>{if(e.target.closest('[data-action="submit-finding-review"]')){e.preventDefault();e.stopImmediatePropagation();submitFindingReview()}if(e.target.closest('[data-action="select-notification"]')&&state.role==='applicant'){let n=e.target.closest('[data-action="select-notification"]');e.preventDefault();e.stopImmediatePropagation();state.notifications=false;loadApplicant(n.dataset.id).then(()=>{state.view='applicant-requests';render()})}},true);document.addEventListener('click',handleClick);document.addEventListener('click',e=>{if(e.target.closest('[data-action="navigate"]'))document.body.classList.remove('nav-open')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();state.notifications=false;renderNotificationPanel()}if(e.key==='Enter'&&e.target.matches('tr[data-action="open-case"]'))openCase(e.target.dataset.id);if(e.key==='Tab'&&e.target.matches('.tab')){let tabs=[...e.target.parentElement.querySelectorAll('.tab')],i=tabs.indexOf(e.target),n=tabs[(i+(e.shiftKey?-1:1)+tabs.length)%tabs.length];n.focus();e.preventDefault()}});$('#notification-button').addEventListener('click',()=>{state.notifications=!state.notifications;renderNotificationPanel()});$('#mobile-menu').addEventListener('click',()=>document.body.classList.toggle('nav-open'));document.addEventListener('click',e=>{if(!e.target.closest('#notification-panel')&&!e.target.closest('#notification-button')&&state.notifications){state.notifications=false;renderNotificationPanel()}});$('#content').addEventListener('submit',e=>{if(e.target.id==='application-wizard'){e.preventDefault();saveFormState();if(!validateStep(e.target)){toast('Check the highlighted fields and try again.','error');return}Object.assign(state.formData,Object.fromEntries(new FormData(e.target)));if(state.formStep<3){state.formStep++;render()}else submitWizard()}})}
function bindExtraActions(){document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;if(t.dataset.action==='upload-docs'&&!$('#upload-input')){e.preventDefault();e.stopImmediatePropagation();showModal('Upload supporting documents',`<p>These files will be attached to ${esc(state.selected?.applicant_name||'this application')}. PDF, JPG or PNG files up to 10 MB.</p><label class="form-label">Choose files<input class="input" id="case-upload-input" type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.txt,.csv"></label><p class="muted">Do not upload real applicant identity or bank information to this demo.</p>`,`<button class="btn quiet" data-action="close-modal">Cancel</button><button class="btn primary" data-action="case-upload-submit">Upload files</button>`);return}if(t.dataset.action==='case-upload-submit'){e.preventDefault();e.stopImmediatePropagation();let files=$('#case-upload-input')?.files;if(!files?.length){toast('Choose at least one file to upload.','error');return}closeModal();handleUpload(files);return}if(t.dataset.action==='replace-doc'){e.preventDefault();e.stopImmediatePropagation();state.replaceDoc=t.dataset.id;showModal('Replace supporting document','Choose the corrected file. The current file will remain until the new upload completes.',`<label class="form-label">Replacement file<input class="input" id="replacement-input" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt,.csv"></label>`,`<button class="btn quiet" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-replacement">Upload replacement</button>`);return}if(t.dataset.action==='submit-replacement'){e.preventDefault();e.stopImmediatePropagation();let files=$('#replacement-input')?.files;if(!files?.length){toast('Choose a replacement file first.','error');return}closeModal();handleUpload(files)}} ,true)}

async function init(){bindGlobal();bindExtraActions();document.body.addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();submitAuth(e.target)}});document.body.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]');if(mode){renderAuth(mode.dataset.authMode);return}const toggle=e.target.closest('[data-auth-password]');if(toggle){const input=$('#auth-password'),shown=input.type==='password';input.type=shown?'text':'password';toggle.setAttribute('aria-pressed',String(shown));toggle.setAttribute('aria-label',shown?'Hide password':'Show password');return}if(e.target.closest('[data-auth-forgot]'))renderAuth('login','Password recovery is not configured in this local version, so no reset link can be sent. Sign in with your existing password; email recovery requires a mail service to be connected.','notice')});document.body.classList.toggle('reduce-motion',localStorage.getItem('ldv-pref-motion')==='on');try{state.user=await api('/auth/me')}catch{renderAuth('login');return}document.body.classList.remove('unauthenticated');$('#auth-screen').hidden=true;await initWorkspace()}
init();
